sources.app.tsx:
// @name Medication reminder
// @background #f1f5f9
// @refresh 3600
// A medication schedule for a frame by the kitchen table or the bed. At each
// dose's time the frame wakes and chimes on its buzzer (frameos.tone, where it
// has one and the scene's Sound is on), shows what to take in large type with
// a big Taken button, and keeps today's checklist: to come, due, taken at
// 08:12, missed. A dose not taken rings again after "Remind again after"
// (three times at most), then shows as missed; one missed by hours (the frame
// was off) is shown as missed without a sound. The last seven days are a
// small strip of bars.
//
// The schedule is the scene's Schedule setting, one medication per line,
// times first: "08:00 Vitamin D", "08:00, 20:00 Metformin 500 mg - with
// food", "every 8h from 07:00 Ibuprofen", "Mon Wed Fri 13:00 Iron"
// (schedule.ts reads it). What was taken when is kept on disk, a day at a
// time (doses.ts).
//
// Touch: Taken, or a row to tick it off (a ticked row asks before it is
// unticked). Keys: the frame's Next and Prev walk the rows, and its Action
// key marks what is due now as taken.
import { parseSchedule, timeLabel } from './schedule'
import {
  MAX_AGAIN,
  dayKey,
  nextChange,
  nextRingAt,
  plusDays,
  readLog,
  rollDay,
  secondsUntil,
  statusOf,
  stripDays,
  tally,
  timedDoses,
  toRing,
} from './doses'

const SAMPLE = '08:00 Vitamin D\n08:00, 20:00 Metformin 500 mg - with food\nevery 8h from 07:00 Ibuprofen 200 mg\nMon Wed Fri 13:00 Iron'

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-slate-100 text-slate-800',
    muted: 'text-slate-500',
    card: 'bg-white',
    rowDue: 'bg-amber-100',
    // The big card: a dose due (the one strong color), the next one, all taken.
    due: 'bg-teal-800 text-white',
    dueMuted: 'text-teal-100',
    taken: 'bg-amber-400 text-slate-900 active:bg-amber-500',
    next: 'bg-white text-slate-800',
    nextMuted: 'text-slate-500',
    done: 'bg-emerald-700 text-white',
    doneMuted: 'text-emerald-100',
    doneMark: 'bg-white text-emerald-700',
    // A row's circle and its chip, by where the dose stands.
    box: 'border-2 border-slate-300',
    boxDue: 'border-4 border-amber-500',
    boxMissed: 'border-2 border-rose-500 text-rose-600',
    boxOff: 'border-2 border-slate-200',
    boxOn: 'bg-emerald-600 text-white',
    dim: 'text-slate-400',
    chipDue: 'bg-amber-400 text-slate-900',
    chipMissed: 'bg-rose-600 text-white',
    chipTaken: 'text-emerald-700',
    button: 'bg-slate-200 text-slate-700 active:bg-slate-300',
    undo: 'bg-rose-600 text-white active:bg-rose-700',
    notice: 'bg-amber-100 text-amber-900',
    missedBox: 'bg-rose-50 text-rose-800',
    // The week's strip and the round panel's ring.
    track: 'bg-slate-200',
    full: 'bg-emerald-500',
    part: 'bg-amber-400',
    ring: '#10b981',
    ringTrack: '#e2e8f0',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    rowDue: 'bg-white border-4 border-black',
    due: 'bg-black text-white',
    dueMuted: 'text-white',
    taken: 'bg-white text-black',
    next: 'bg-white text-black border-4 border-black',
    nextMuted: 'text-black',
    done: 'bg-white text-black border-4 border-black',
    doneMuted: 'text-black',
    doneMark: 'bg-black text-white',
    box: 'border-4 border-black',
    boxDue: 'border-4 border-black',
    boxMissed: 'border-4 border-black text-black',
    boxOff: 'border-2 border-black',
    boxOn: 'bg-black text-white',
    dim: 'text-black',
    chipDue: 'bg-black text-white',
    chipMissed: 'bg-white text-black border-2 border-black',
    chipTaken: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    undo: 'bg-black text-white',
    notice: 'bg-white text-black border-2 border-black',
    missedBox: 'bg-white text-black border-2 border-black',
    track: 'bg-white border-2 border-black',
    full: 'bg-black',
    part: 'bg-black',
    ring: '#000000',
    ringTrack: '#ffffff',
  },
}

// Color e-paper (Spectra's six inks): the high-contrast page with the due
// card, the ticks and the missed chips in solid inks, as the panel shows
// them, so nothing is dithered into confetti.
THEMES.inks = {
  ...THEMES.high,
  due: 'bg-[#18539a] text-white',
  boxOn: 'bg-[#2a5531] text-white',
  chipDue: 'bg-[#18539a] text-white',
  chipMissed: 'bg-[#6b1119] text-white',
  boxMissed: 'border-4 border-[#6b1119] text-[#6b1119]',
  missedBox: 'bg-white text-[#6b1119] border-2 border-[#6b1119]',
  full: 'bg-[#2a5531]',
  part: 'bg-[#18539a]',
  ring: '#2a5531',
}

const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// A panel of 900 px or more on its shorter side at render scale 1 (a 13.3"
// color e-paper, 1200 px) draws everything that much larger (K), by halves:
// S() turns Tailwind's sizes in a class list into pixels times K. Elsewhere K
// is 1 and the classes stay as they are.
let K = 1
const TEXT = {
  xs: [12, 16], sm: [14, 20], base: [16, 24], lg: [18, 28], xl: [20, 28], '2xl': [24, 32],
  '3xl': [30, 36], '4xl': [36, 40], '5xl': [48, 48], '6xl': [60, 60], '7xl': [72, 72],
}
const RADII = { md: 6, lg: 8, xl: 12, '2xl': 16, '3xl': 24 }
const S = (cls) => (K === 1 ? cls : cls.split(' ').map((c) => {
  let m = /^text-(xs|sm|base|lg|xl|[2-7]xl)$/.exec(c)
  if (m) return `text-[${Math.round(TEXT[m[1]][0] * K)}px] leading-[${Math.round(TEXT[m[1]][1] * K)}px]`
  m = /^rounded-(md|lg|xl|2xl|3xl)$/.exec(c)
  if (m) return `rounded-[${Math.round(RADII[m[1]] * K)}px]`
  m = /^border-(\d+)$/.exec(c)
  if (m) return `border-${Math.min(8, Math.round(Number(m[1]) * K))}`
  m = /^(h|w|p|px|py|pl|pr|pt|pb|gap|mt|mb)-(\d+)$/.exec(c)
  if (m) return `${m[1]}-[${Math.round(Number(m[2]) * 4 * K)}px]`
  return c
}).join(' '))
const k = (n) => Math.round(n * K)

// What get() worked out, for the components and the handlers: the schedule,
// today's doses and the day's record, and the settings that shape them.
let meds = []
let problems = []
let doses = []
let log = readLog(null, 0)
let again = 10
let twelve = false
// The big card's view and the tally, worked out with the rows' statuses.
let hero = { kind: 'empty', items: [], at: 0, when: '', ringAt: 0, missed: [], last: 0, lastTaken: [] }
let counts = { taken: 0, of: 0, missed: 0, due: 0 }
let strip = []
// A layout whose shape changes once nothing is due (a small panel's list
// comes back under the card): Taken there sets no signal, so get() runs.
let wholeAfterTaken = false

// What a tap changes, a signal each: a row's status, when it was taken and
// whether it asks to be unticked; the big card, the tally and the strip (each
// by a key of what it shows). A tap runs only what reads them, not get().
const rows = []
const row = (i) => (rows[i] ??= { st: signal('upcoming'), at: signal(0), ask: signal(false) })
const heroKey = signal('')
const tallyKey = signal('')

const save = () => frameos.setState('log', log)

// The schedule, the settings and the day's record as they are now: a new day
// puts the day before into the history first. True when the record changed.
function load(app, now) {
  const parsed = parseSchedule(app.state.schedule ?? SAMPLE)
  meds = parsed.meds
  problems = parsed.problems
  again = Math.max(0, Math.min(120, Number(app.state.remindAgain ?? 10) || 0))
  twelve = app.state.clock === '12'
  const kept = app.state.log
  const read = readLog(kept, now)
  log = rollDay(read, meds, now, again)
  doses = timedDoses(meds, new Date(now))
  return log !== read || !kept || typeof kept !== 'object' || kept.day !== read.day
}

// The next doses after today's: the first time on the next day that has any.
function laterDoses(now) {
  const today = new Date(now)
  for (let ahead = 1; ahead <= 7; ahead++) {
    const day = plusDays(today, ahead)
    const list = timedDoses(meds, day)
    if (list.length) {
      return { items: list.filter((d) => d.at === list[0].at), at: list[0].at, when: ahead === 1 ? 'Tomorrow' : DAYS[day.getDay()] }
    }
  }
  return { items: [], at: 0, when: '' }
}

// Every status, the card and the tally, into their signals.
function show(now = Date.now()) {
  const asking = frameos.recall('asking') || ''
  const statuses = doses.map((d) => statusOf(d, now, log, again))
  doses.forEach((d, i) => {
    const r = row(i)
    r.st.value = statuses[i]
    r.at.value = log.taken[d.key] || 0
    r.ask.value = asking === d.key
  })
  counts = tally(doses, now, log, again)
  strip = stripDays(log, counts, now)
  const due = doses.filter((_, i) => statuses[i] === 'due')
  const upcoming = doses.filter((_, i) => statuses[i] === 'upcoming')
  // Under the next dose: what was missed today, else what was taken last
  // (one press, give or take a few minutes): "did I take it?" at a glance.
  const missed = doses.filter((_, i) => statuses[i] === 'missed')
  const last = Math.max(0, ...doses.map((d) => log.taken[d.key] || 0))
  const lastTaken = last ? doses.filter((d) => log.taken[d.key] && last - log.taken[d.key] < 5 * 60 * 1000) : []
  const after = { ringAt: 0, missed, last, lastTaken }
  if (due.length) {
    const rings = due.map((d) => nextRingAt(d, now, again)).filter((at) => at !== null)
    hero = { ...after, kind: 'due', items: due, at: due[0].at, when: '', ringAt: rings.length ? Math.min(...rings) : 0 }
  } else if (!meds.length) {
    hero = { ...after, kind: 'empty', items: [], at: 0, when: '' }
  } else if (upcoming.length) {
    hero = { ...after, kind: 'next', items: upcoming.filter((d) => d.at === upcoming[0].at), at: upcoming[0].at, when: '' }
  } else {
    hero = { ...after, kind: counts.of > 0 && counts.taken === counts.of ? 'done' : 'next', ...laterDoses(now) }
  }
  heroKey.value = [
    hero.kind, hero.at, hero.when, hero.ringAt, twelve, hero.last, counts.taken, counts.of,
    ...hero.items.map((d) => d.key), ...missed.map((d) => `!${d.key}`), ...lastTaken.map((d) => `+${d.key}`),
  ].join('|')
  tallyKey.value = [counts.taken, counts.of, counts.missed, strip.map((c) => `${c.taken}/${c.of}`).join(',')].join('|')
}

// A handler that finds the day has turned since get() starts it and sets no
// signal: the list changes shape, so a whole get() draws it.
function sameDay(now) {
  if (dayKey(new Date(now)) === log.day) return true
  log = rollDay(log, meds, now, again)
  doses = timedDoses(meds, new Date(now))
  return false
}

// Taken: every dose the card shows as due, now.
function takeDue() {
  const now = Date.now()
  const same = sameDay(now)
  const items = same ? hero.items : doses.filter((d) => statusOf(d, now, log, again) === 'due')
  if (hero.kind !== 'due' && same) return
  log.taken = { ...log.taken }
  for (const dose of items) log.taken[dose.key] = now
  frameos.remember('asking', '')
  save()
  if (same && !wholeAfterTaken) show(now)
}

// A row: ticked off now, or (when it is ticked) asked whether to untick it.
function toggle(i) {
  const now = Date.now()
  if (!sameDay(now)) return
  const dose = doses[i]
  if (!dose) return
  if (log.taken[dose.key]) {
    frameos.remember('asking', dose.key)
  } else {
    log.taken = { ...log.taken, [dose.key]: now }
    frameos.remember('asking', '')
    save()
  }
  show(now)
}
function untick(i) {
  const dose = doses[i]
  if (dose) {
    log.taken = { ...log.taken }
    delete log.taken[dose.key]
    save()
  }
  frameos.remember('asking', '')
  show()
}
function keep() {
  frameos.remember('asking', '')
  show()
}

const openSettings = () => {
  if (typeof frameos.dispatch === 'function') frameos.dispatch('sceneSettings')
}

const Check = ({ size }) => (
  <svg className={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

const Pencil = ({ size }) => (
  <svg className={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 20h4L19 9l-4-4L4 16v4M13.5 6.5l4 4" />
  </svg>
)

// "tomorrow 07:00", "Monday 07:00": a later day's dose inside a sentence.
const when = (at, label) => (label ? `${label === 'Tomorrow' ? 'tomorrow' : label} ${timeLabel(at, twelve)}` : timeLabel(at, twelve))
// A moment's clock time: "08:12".
const clockAt = (ms) => {
  const d = new Date(ms)
  return timeLabel(d.getHours() * 60 + d.getMinutes(), twelve)
}

// The big card's sizes: lg fills a tall card (a landscape panel's left half,
// a portrait panel's top), md is as tall as it needs on a square or short
// panel (a 480x480), sm on a watch or a 2.8" LCD.
const SIZES = {
  lg: {
    box: 'p-5 gap-2 rounded-2xl', kicker: 'text-lg', at: 'text-3xl', names: 'text-3xl', note: 'text-lg', gap: 'gap-3',
    button: 'h-20 text-4xl gap-3 rounded-2xl mt-2', check: 'w-10 h-10', next: 'text-6xl', many: 3, more: true,
    mark: 'w-20 h-20', markCheck: 'w-12 h-12', done: 'text-4xl mt-2', foot: 'text-lg', footSmall: 'text-sm',
  },
  md: {
    box: 'p-4 gap-1 rounded-2xl', kicker: 'text-base', at: 'text-2xl', names: 'text-2xl', note: 'text-base', gap: 'gap-2',
    button: 'h-14 text-3xl gap-2 rounded-xl mt-2', check: 'w-8 h-8', next: 'text-5xl', many: 2, more: true,
    mark: 'w-14 h-14', markCheck: 'w-9 h-9', done: 'text-3xl mt-1', foot: 'text-base', footSmall: 'text-xs',
  },
  sm: {
    box: 'p-3 gap-1 rounded-xl', kicker: 'text-sm', at: 'text-xl', names: 'text-xl', note: 'text-sm', gap: 'gap-1',
    button: 'h-12 text-2xl gap-2 rounded-xl mt-1', check: 'w-6 h-6', next: 'text-4xl', many: 2, more: false,
    mark: 'w-12 h-12', markCheck: 'w-8 h-8', done: 'text-2xl', foot: '', footSmall: '',
  },
}

// The big card: what to take now and Taken, else the next dose, else all
// taken. `fill`: as tall as its box (lg), else as tall as it needs.
const Hero = memo(({ t, size, fill }) => {
  heroKey.value
  const z = SIZES[size] || SIZES.lg
  const box = S(`flex flex-col ${fill ? 'h-full' : ''} ${z.box}`)
  const kicker = S(`${z.kicker} font-bold uppercase`)
  const names = S(`${z.names} font-bold leading-tight`)
  const note = S(z.note)
  // The names take what the card leaves them where it fills its box, and
  // are cut there rather than drawn over the button.
  const middle = `${fill ? 'flex-1 min-h-0 overflow-hidden' : ''} flex flex-col ${S(z.gap)}`
  if (hero.kind === 'due') {
    const shown = hero.items.slice(0, z.many)
    const more = hero.items.length - shown.length
    const mixed = hero.items.some((d) => d.at !== hero.at)
    return (
      <div className={`${box} ${t.due}`}>
        <div className="flex items-baseline justify-between gap-2">
          <span className={`${kicker} ${t.dueMuted}`}>Take now</span>
          <span className={S(`${z.at} font-bold`)}>{timeLabel(hero.at, twelve)}</span>
        </div>
        <div className={`${middle} ${fill ? 'justify-center' : ''}`}>
          {shown.map((d) => (
            <div className="flex flex-col">
              <span className={`${names} line-clamp-2`}>{mixed ? `${timeLabel(d.at, twelve)} ${d.name}` : d.name}</span>
              {d.note ? <span className={`${note} ${t.dueMuted} truncate`}>{d.note}</span> : null}
            </div>
          ))}
          {more > 0 ? <span className={`${note} ${t.dueMuted}`}>{`and ${more} more`}</span> : null}
        </div>
        {hero.ringAt && z.more ? (
          <span className={S(`${z.footSmall === 'text-xs' ? 'text-sm' : 'text-base'} ${t.dueMuted}`)}>{`Reminder again at ${clockAt(hero.ringAt)}`}</span>
        ) : null}
        <div className={S(`${z.button} shrink-0 flex items-center justify-center font-bold ${t.taken}`)} onClick={takeDue}>
          <Check size={S(z.check)} />
          <span>Taken</span>
        </div>
      </div>
    )
  }
  if (hero.kind === 'empty') {
    return (
      <div className={`${box} ${t.next} ${fill ? 'justify-center' : ''}`}>
        <span className={names}>No medications yet</span>
        <span className={`${note} ${t.nextMuted}`}>Add them in this scene's Schedule setting, one per line, like 08:00 Vitamin D.</span>
        <div className={S(`${size === 'sm' ? 'h-10 px-3 text-base mt-1' : 'h-12 px-5 text-lg mt-3'} self-start rounded-xl flex items-center font-bold ${t.button}`)} onClick={openSettings}>
          Edit schedule
        </div>
      </div>
    )
  }
  if (hero.kind === 'done') {
    return (
      <div className={`${box} ${t.done} items-center justify-center text-center`}>
        <div className={S(`${z.mark} rounded-full flex items-center justify-center ${t.doneMark}`)}>
          <Check size={S(z.markCheck)} />
        </div>
        <span className={S(`${z.done} font-bold`)}>All taken today</span>
        {hero.items.length ? (
          <span className={`${note} ${t.doneMuted} line-clamp-2`}>{`Next: ${when(hero.at, hero.when)} ${hero.items.map((d) => d.name).join(', ')}`}</span>
        ) : null}
      </div>
    )
  }
  const shown = hero.items.slice(0, size === 'sm' ? 1 : z.many)
  const more = hero.items.length - shown.length
  const named = (list) => list.map((d) => d.name).join(', ')
  return (
    <div className={`${box} ${t.next}`}>
      <span className={`${kicker} ${t.nextMuted}`}>{hero.when ? `Next: ${hero.when}` : 'Next dose'}</span>
      <span className={S(`${z.next} font-bold`)}>{timeLabel(hero.at, twelve)}</span>
      <div className={middle}>
        {shown.map((d) => (
          <div className="flex flex-col">
            <span className={`${names} line-clamp-2`}>{d.name}</span>
            {d.note ? <span className={`${note} ${t.nextMuted} truncate`}>{d.note}</span> : null}
          </div>
        ))}
        {more > 0 ? <span className={`${note} ${t.nextMuted}`}>{`and ${more} more`}</span> : null}
      </div>
      {!z.more ? null : hero.missed.length ? (
        <div className={S(`shrink-0 flex flex-col px-3 py-2 rounded-xl ${fill ? '' : 'mt-2'} ${t.missedBox}`)}>
          <span className={S(`${z.foot} font-bold line-clamp-2`)}>{`Missed: ${hero.missed.map((d) => `${timeLabel(d.at, twelve)} ${d.name}`).join(', ')}`}</span>
          <span className={S(z.footSmall)}>Took it after all? Tap it in the list.</span>
        </div>
      ) : hero.last ? (
        <div className={S(`shrink-0 flex items-start gap-2 ${fill ? '' : 'mt-2'} ${t.nextMuted}`)}>
          <Check size={S('w-6 h-6 shrink-0')} />
          <span className={S(`${z.foot} line-clamp-2`)}>{`Taken at ${clockAt(hero.last)}: ${named(hero.lastTaken)}`}</span>
        </div>
      ) : null}
    </div>
  )
})

// "4 of 6 taken, 1 missed".
const Tally = memo(({ t, small }) => {
  tallyKey.value
  const text = counts.of ? `${counts.taken} of ${counts.of} taken${counts.missed ? `, ${counts.missed} missed` : ''}` : 'Nothing today'
  return <span className={S(`${small ? 'text-sm' : 'text-base'} ${t.muted} truncate`)}>{text}</span>
})

// The last seven days as bars, today last: full for all taken, as tall as
// the share taken, an empty track for a day with nothing on record.
const Strip = memo(({ t }) => {
  tallyKey.value
  const barH = k(30)
  return (
    <div className={`flex items-end ${S('gap-1')}`}>
      {strip.map((c) => {
        const share = c.of > 0 ? c.taken / c.of : 0
        const fillH = Math.round(share * barH)
        return (
          <div className={`flex flex-col items-center ${S('gap-1')}`}>
            <div className={`flex flex-col justify-end w-[${k(14)}px] h-[${barH}px] rounded-[${k(3)}px] ${t.track}`}>
              {fillH > 0 ? <div className={`h-[${fillH}px] rounded-[${k(3)}px] ${share >= 1 ? t.full : t.part}`} /> : null}
            </div>
            <span className={S(`text-xs ${c.today ? 'font-bold underline' : t.muted}`)}>{DAYS[c.weekday].charAt(0)}</span>
          </div>
        )
      })}
    </div>
  )
})

// A row's circle: ticked, due (a strong ring), missed (an !), to come, or not
// counted.
const Tick = ({ st, t, small }) => {
  const size = S(small ? 'w-7 h-7' : 'w-8 h-8')
  if (st === 'taken') {
    return (
      <div className={`${size} shrink-0 rounded-full flex items-center justify-center ${t.boxOn}`}>
        <Check size={S('w-5 h-5')} />
      </div>
    )
  }
  const look = st === 'due' ? t.boxDue : st === 'missed' ? t.boxMissed : st === 'untracked' ? t.boxOff : t.box
  return (
    <div className={`${size} shrink-0 rounded-full flex items-center justify-center ${look}`}>
      {st === 'missed' ? <span className={S('text-base font-bold')}>!</span> : null}
    </div>
  )
}

// One dose of today's list: its circle, time and name, and how it stands.
const Row = memo(({ i, t, small, time, timeW, name }) => {
  const r = rows[i]
  const st = r.st.value
  const at = r.at.value
  const words = S(small ? 'text-base' : 'text-lg')
  const height = S(small ? 'h-11' : 'h-14')
  if (r.ask.value) {
    return (
      <div className={`flex items-center ${height} ${S(small ? 'gap-1 px-2 rounded-xl' : 'gap-2 px-3 rounded-xl')} ${t.card}`}>
        <span className={`flex-1 min-w-0 truncate ${words}`}>{`Untick ${name}?`}</span>
        <div className={S(`${small ? 'h-8 px-2 text-sm' : 'h-10 px-4 text-base'} rounded-xl flex items-center ${t.button}`)} onClick={keep}>
          Keep
        </div>
        <div className={S(`${small ? 'h-8 px-2 text-sm' : 'h-10 px-4 text-base'} rounded-xl flex items-center font-bold ${t.undo}`)} onClick={() => untick(i)}>
          Untick
        </div>
      </div>
    )
  }
  const quiet = st === 'taken' || st === 'untracked' ? t.dim : ''
  const chip = S(`${small ? 'text-xs px-1 h-6' : 'text-sm px-2 h-7'} shrink-0 rounded-lg flex items-center`)
  return (
    <div className={`flex items-center ${height} ${S(small ? 'gap-2 px-2 rounded-xl' : 'gap-3 px-3 rounded-xl')} ${st === 'due' ? t.rowDue : t.card}`}
      onClick={() => toggle(i)}>
      <Tick st={st} t={t} small={small} />
      <span className={`w-[${timeW}px] shrink-0 ${words} font-bold ${quiet}`}>{time}</span>
      <span className={`flex-1 min-w-0 truncate ${words} ${quiet}`}>{name}</span>
      {small ? null : st === 'taken' ? <span className={`${chip} ${t.chipTaken}`}>{`taken ${clockAt(at)}`}</span>
        : st === 'due' ? <span className={`${chip} font-bold ${t.chipDue}`}>Due</span>
        : st === 'missed' ? <span className={`${chip} font-bold ${t.chipMissed}`}>Missed</span>
        : st === 'untracked' ? <span className={`${chip} ${t.dim}`}>not counted</span> : null}
    </div>
  )
})

// A line of the schedule that could not be read, and why.
const Problem = ({ p, t, small }) => (
  <div className={S(`flex flex-col ${small ? 'p-2 text-xs' : 'px-3 py-2 text-sm'} rounded-xl ${t.notice}`)}>
    <span className="font-bold truncate">{`Line ${p.line} not read: ${p.text}`}</span>
    <span>{`${p.why.charAt(0).toUpperCase()}${p.why.slice(1)}.`}</span>
  </div>
)

// With no schedule yet: how to write one.
const Examples = ({ t, small }) => (
  <div className={S(`flex flex-col ${small ? 'gap-1 p-2 text-sm' : 'gap-1 p-4 text-lg'} rounded-xl ${t.card}`)}>
    <span className="font-bold">One medication per line, times first:</span>
    {SAMPLE.split('\n').map((line) => <span className="font-mono truncate">{line}</span>)}
    <span className={t.muted}>A note goes after a dash. Days are optional.</span>
  </div>
)

// Today's list: the lines it could not read first, then every dose.
const Rows = ({ t, small }) => {
  const timeW = k(small ? (twelve ? 64 : 46) : twelve ? 78 : 56)
  return (
    <div className={`flex flex-col ${S(small ? 'gap-1' : 'gap-2')}`}>
      {problems.slice(0, 3).map((p) => <Problem p={p} t={t} small={small} />)}
      {doses.map((d, i) => <Row i={i} t={t} small={small} time={timeLabel(d.at, twelve)} timeW={timeW} name={d.name} />)}
      {!doses.length && meds.length ? <span className={S(`${small ? 'text-sm' : 'text-lg'} ${t.muted}`)}>Nothing to take today.</span> : null}
      {!meds.length && !problems.length ? <Examples t={t} small={small} /> : null}
    </div>
  )
}

// The list in a box that scrolls: `boxH` tall (whole rows), else what is left.
const List = ({ t, small, boxH }) => (
  <div className={`${boxH ? `h-[${boxH}px]` : 'flex-1'} min-h-0 overflow-y-auto`}>
    <Rows t={t} small={small} />
  </div>
)

// On a small panel, above the list when nothing is due: the next dose on one
// line, all taken, or where the schedule goes.
const NextLine = memo(({ t }) => {
  heroKey.value
  const box = 'flex items-center gap-2 h-11 px-2 rounded-xl'
  if (hero.kind === 'empty') {
    return (
      <div className={`${box} ${t.card}`} onClick={openSettings}>
        <span className="flex-1 min-w-0 text-sm truncate">No medications yet: edit the schedule</span>
        <Pencil size="w-5 h-5 shrink-0" />
      </div>
    )
  }
  if (hero.kind === 'done') {
    return (
      <div className={`${box} ${t.done}`}>
        <Check size="w-5 h-5 shrink-0" />
        <span className="flex-1 min-w-0 text-base font-bold truncate">All taken today</span>
      </div>
    )
  }
  return (
    <div className={`${box} ${t.next}`}>
      <span className={`text-sm uppercase font-bold ${t.nextMuted}`}>{hero.when ? hero.when.slice(0, 3) : 'Next'}</span>
      <span className="text-lg font-bold">{timeLabel(hero.at, twelve)}</span>
      <span className="flex-1 min-w-0 text-base truncate">{hero.items.map((d) => d.name).join(', ')}</span>
    </div>
  )
})

// "Saturday 28 Nov": the day, which a pill box is for.
const dateLine = (now) => {
  const d = new Date(now)
  return `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()].slice(0, 3)}`
}

// The head of today's list: the day, the tally, the week, and the schedule.
const Head = ({ t, now, small }) => (
  <div className={`flex items-center ${S(small ? 'gap-2' : 'gap-3')}`}>
    <div className="flex-1 min-w-0 flex flex-col">
      <span className={S(`${small ? 'text-lg' : 'text-2xl'} font-bold truncate`)}>{small ? DAYS[new Date(now).getDay()] : dateLine(now)}</span>
      <Tally t={t} small={small} />
    </div>
    {small ? null : <Strip t={t} />}
    <div className={S(`${small ? 'w-9 h-9' : 'w-11 h-11'} shrink-0 rounded-xl flex items-center justify-center ${t.button}`)}
      title="Edit the schedule" onClick={openSettings}>
      <Pencil size={S(small ? 'w-5 h-5' : 'w-6 h-6')} />
    </div>
  </div>
)

// Whole rows in the list's box: no row shows cut in half at its foot. With
// notes about the schedule (their height is their words') the box takes
// what is left.
function wholeRows(room, small) {
  if (problems.length) return 0
  const rowH = k(small ? 44 : 56)
  const gap = k(small ? 4 : 8)
  const fit = Math.max(1, Math.floor((room + gap) / (rowH + gap)))
  return doses.length > fit ? fit * rowH + (fit - 1) * gap : 0
}

// On a round panel: the day's share taken as a ring along the rim, the
// tally in the arc at the top, and the card and the list below it in the
// square inside the circle, which scrolls.
const Ring = memo(({ W, H, t }) => {
  tallyKey.value
  const cx = W / 2, cy = H / 2, rr = Math.min(W, H) / 2 - 6
  const share = counts.of ? counts.taken / counts.of : 0
  const a = share * 2 * Math.PI
  const x = (cx + rr * Math.sin(a)).toFixed(1), y = (cy - rr * Math.cos(a)).toFixed(1)
  const arc = share >= 1
    ? `M ${cx} ${cy - rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy + rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy - rr}`
    : `M ${cx} ${cy - rr} A ${rr} ${rr} 0 ${share > 0.5 ? 1 : 0} 1 ${x} ${y}`
  return (
    <svg className={`absolute left-0 top-0 w-[${W}px] h-[${H}px]`} viewBox={`0 0 ${W} ${H}`} fill="none" strokeWidth={8} strokeLinecap="round">
      <circle cx={cx} cy={cy} r={rr} stroke={t.ringTrack} />
      {share > 0 ? <path d={arc} stroke={t.ring} /> : null}
    </svg>
  )
})

// A round panel shows one of two pages: the dose page, the whole circle with
// what to take or what comes next and Taken or the list in the arc below;
// and the list, in the square inside the circle, which scrolls, Back below.
const page = (to) => frameos.remember('page', to)
const chordAt = (R, dy) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))

const RoundNow = memo(({ t, W, H }) => {
  heroKey.value
  const R = Math.min(W, H) / 2 - 12
  const cx = W / 2
  const cy = H / 2
  const big = R >= 180
  const kind = hero.kind
  const look = kind === 'due' ? t.due : kind === 'done' ? t.done : t.page
  const muted = kind === 'due' ? t.dueMuted : kind === 'done' ? t.doneMuted : t.muted
  // The words between 0.72 R above the middle and 0.4 R below it, as wide as
  // the circle is at their top; the button under them, as wide as its chord.
  const top = Math.round(cy - R * 0.72)
  const colW = chordAt(R, R * 0.72) - 16
  const colH = Math.round(R * 1.12)
  const btnH = big ? 56 : 44
  const btnTop = Math.round(cy + R * 0.46)
  const btnW = Math.min(big ? 260 : 180, chordAt(R, btnTop + btnH - cy) - 24)
  const tallyTop = Math.round(cy - R + (big ? 18 : 10))
  const tallyW = chordAt(R, R - (big ? 30 : 20))
  const tallyText = counts.of ? `${counts.taken} of ${counts.of} taken` : ''
  const names = big ? 'text-3xl' : 'text-xl'
  let body
  if (kind === 'due') {
    const shown = hero.items.slice(0, 2)
    body = (
      <>
        <span className={`${big ? 'text-base' : 'text-xs'} font-bold uppercase ${muted}`}>Take now</span>
        <span className={`${big ? 'text-4xl' : 'text-2xl'} font-bold`}>{timeLabel(hero.at, twelve)}</span>
        {shown.map((d) => (
          <div className="flex flex-col items-center">
            <span className={`${names} font-bold leading-tight line-clamp-2`}>{d.name}</span>
            {d.note ? <span className={`${big ? 'text-base' : 'text-xs'} ${muted} truncate`}>{d.note}</span> : null}
          </div>
        ))}
        {hero.items.length > 2 ? <span className={`text-sm ${muted}`}>{`and ${hero.items.length - 2} more`}</span> : null}
      </>
    )
  } else if (kind === 'done') {
    body = (
      <>
        <div className={`${big ? 'w-16 h-16' : 'w-10 h-10'} rounded-full flex items-center justify-center ${t.doneMark}`}>
          <Check size={big ? 'w-10 h-10' : 'w-6 h-6'} />
        </div>
        <span className={`${big ? 'text-3xl' : 'text-xl'} font-bold`}>All taken today</span>
        {hero.items.length ? (
          <span className={`${big ? 'text-base' : 'text-xs'} ${muted} line-clamp-2`}>{`Next: ${when(hero.at, hero.when)} ${hero.items.map((d) => d.name).join(', ')}`}</span>
        ) : null}
      </>
    )
  } else if (kind === 'empty') {
    body = (
      <>
        <span className={`${big ? 'text-2xl' : 'text-lg'} font-bold`}>No medications yet</span>
        <span className={`${big ? 'text-base' : 'text-xs'} ${muted}`}>Add them in this scene's Schedule setting, like 08:00 Vitamin D.</span>
      </>
    )
  } else {
    body = (
      <>
        <span className={`${big ? 'text-base' : 'text-xs'} font-bold uppercase ${muted}`}>{hero.when ? `Next: ${hero.when}` : 'Next dose'}</span>
        <span className={`${big ? 'text-6xl' : 'text-4xl'} font-bold`}>{timeLabel(hero.at, twelve)}</span>
        <span className={`${big ? 'text-2xl' : 'text-lg'} font-bold leading-tight line-clamp-2`}>{hero.items.map((d) => d.name).join(', ')}</span>
        {hero.missed.length ? (
          <span className={`${big ? 'text-base' : 'text-xs'} font-bold line-clamp-2 ${t.missedBox} px-2 rounded-lg`}>{`Missed: ${hero.missed.map((d) => d.name).join(', ')}`}</span>
        ) : hero.last ? (
          <span className={`${big ? 'text-base' : 'text-xs'} ${muted} line-clamp-2`}>{`Taken at ${clockAt(hero.last)}: ${hero.lastTaken.map((d) => d.name).join(', ')}`}</span>
        ) : null}
      </>
    )
  }
  const button = kind === 'due'
    ? { label: 'Taken', look: t.taken, act: takeDue, check: true }
    : kind === 'empty'
      ? { label: 'Edit schedule', look: t.button, act: openSettings, check: false }
      : { label: "Today's list", look: t.button, act: () => page('list'), check: false }
  return (
    <div className={`absolute left-0 top-0 w-[${W}px] h-[${H}px] ${look}`}>
      {tallyText ? (
        <div className={`absolute left-[${Math.round(cx - tallyW / 2)}px] top-[${tallyTop}px] w-[${tallyW}px] flex justify-center`}>
          <span className={`${big ? 'text-sm' : 'text-xs'} ${muted}`}>{tallyText}</span>
        </div>
      ) : null}
      <div className={`absolute left-[${Math.round(cx - colW / 2)}px] top-[${top}px] w-[${colW}px] h-[${colH}px] flex flex-col items-center justify-center text-center ${big ? 'gap-2' : 'gap-1'}`}>
        {body}
      </div>
      <div className={`absolute left-[${Math.round(cx - btnW / 2)}px] top-[${btnTop}px] w-[${btnW}px] h-[${btnH}px] rounded-full flex items-center justify-center gap-2 font-bold ${big ? (kind === 'due' ? 'text-3xl' : 'text-xl') : 'text-lg'} ${button.look}`}
        onClick={button.act}>
        {button.check ? <Check size={big ? 'w-8 h-8' : 'w-5 h-5'} /> : null}
        <span>{button.label}</span>
      </div>
    </div>
  )
})

function roundView(t, W, H) {
  const R = Math.min(W, H) / 2 - 12
  const cx = W / 2
  const cy = H / 2
  if (frameos.recall('page') !== 'list') {
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        <RoundNow t={t} W={W} H={H} />
        <Ring W={W} H={H} t={t} />
      </div>
    )
  }
  const side = Math.floor(R * Math.SQRT2)
  const left = Math.round((W - side) / 2)
  const top = Math.round((H - side) / 2)
  const headW = chordAt(R, R - 34)
  const backTop = top + side + 8
  const backW = Math.min(140, chordAt(R, backTop + 40 - cy) - 16)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <Ring W={W} H={H} t={t} />
      <div className={`absolute left-[${Math.round(cx - headW / 2)}px] top-[${Math.round(cy - R + 12)}px] w-[${headW}px] flex flex-col items-center`}>
        <span className="text-lg font-bold">Today</span>
        <Tally t={t} small />
      </div>
      <div className={`absolute left-[${left}px] top-[${top}px] w-[${side}px] h-[${side}px] overflow-y-auto`}>
        <Rows t={t} small />
      </div>
      <div className={`absolute left-[${Math.round(cx - backW / 2)}px] top-[${backTop}px] w-[${backW}px] h-[40px] rounded-full flex items-center justify-center text-base font-bold ${t.button}`}
        onClick={() => page('now')}>
        Back
      </div>
    </div>
  )
}

// The frame's Back keeps a ticked dose that asked to be unticked, as its
// Keep does; its Action key marks what is due as taken, as Taken does.
export function onEvent(app, context) {
  if (context.event === 'back') {
    if (frameos.recall('asking')) {
      frameos.remember('asking', '')
      return true
    }
    if (frameos.recall('page') === 'list') {
      page('now')
      return true
    }
    return false
  }
  if (context.event !== 'button') return false
  const press = context.payload || {}
  if (press.action !== 'press' || (press.role !== 'primary' && press.role !== 'refresh')) return false
  const now = Date.now()
  if (load(app, now)) save()
  const due = doses.filter((d) => statusOf(d, now, log, again) === 'due')
  if (!due.length) return false
  log.taken = { ...log.taken }
  for (const dose of due) log.taken[dose.key] = now
  save()
  return true
}

const soundOn = (app) => String(app.state.sound ?? 'true') !== 'false'

export function get(app, context) {
  const now = Date.now()
  let changed = load(app, now)
  // A dose that has come rings once (the frame's chime), and again every
  // "Remind again after" until it is taken, MAX_AGAIN times more at most.
  const ring = toRing(doses, now, log, again)
  const ringing = Object.keys(ring).length > 0
  if (ringing) {
    log.rang = { ...log.rang, ...ring }
    changed = true
  }
  if (changed) save()
  if (ringing && soundOn(app) && typeof frameos.tone === 'function') frameos.tone()
  // A ring brings a round panel back from its list to the dose and Taken.
  if (ringing && frameos.recall('page') === 'list') page('now')
  // Wake for the next dose, the next reminder, a dose turning missed or the
  // new day, within the scene's own interval.
  const cap = Number(app.state.refreshInterval) > 0 ? Number(app.state.refreshInterval) : 3600
  frameos.setNextSleep(secondsUntil(nextChange(doses, now, log, again), now, cap))
  show(now)

  const t = themeOf(app)
  K = 1
  wholeAfterTaken = false
  if (context?.round === true) return roundView(t, context.imageWidth, context.imageHeight)
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  // A watch, a 2.8" LCD or a small e-paper: less padding, smaller type, and
  // one column that scrolls: what is due fills the screen above the list,
  // else the next dose is a line over it.
  const small = Math.min(W, H) < 320
  if (small) {
    const pad = 10
    const headH = 44
    const view = H - 2 * pad - headH - 8
    wholeAfterTaken = true
    return (
      <div className={`flex flex-col w-full h-full p-[${pad}px] gap-2 ${t.page}`}>
        <div className={`h-[${headH}px] shrink-0 flex flex-col justify-center`}>
          <Head t={t} now={now} small />
        </div>
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className="flex flex-col gap-2">
            {hero.kind === 'due' ? (
              <div className={`h-[${view}px] flex flex-col`}>
                <Hero t={t} size="sm" fill />
              </div>
            ) : (
              <NextLine t={t} />
            )}
            <Rows t={t} small />
          </div>
        </div>
      </div>
    )
  }
  // By both sides, so a 1200x1600 panel is laid out as 600x800 drawn twice
  // as large: room for the list under the card.
  const fit = Math.min(Math.min(W, H) / 480, Math.max(W, H) / 800)
  K = Math.min(W, H) >= 900 ? Math.max(1, Math.min(3, Math.floor(fit * 2) / 2)) : 1
  const pad = k(small ? 10 : 24)
  const gap = k(small ? 8 : 16)
  const headH = k(small ? 48 : 64)
  if (W > H * 1.15 && !small) {
    // Side by side: the card on the left, today's list on the right.
    const heroW = Math.round((W - 2 * pad - gap) * 0.42)
    const boxH = wholeRows(H - 2 * pad - headH - gap, false)
    return (
      <div className={`flex w-full h-full p-[${pad}px] gap-[${gap}px] ${t.page}`}>
        <div className={`w-[${heroW}px] shrink-0 flex flex-col`}>
          <Hero t={t} size="lg" fill />
        </div>
        <div className={`flex-1 min-w-0 flex flex-col gap-[${gap}px]`}>
          <div className={`h-[${headH}px] flex flex-col justify-center`}>
            <Head t={t} now={now} small={false} />
          </div>
          <List t={t} small={false} boxH={boxH} />
        </div>
      </div>
    )
  }
  // Stacked: the day, the card, the list. On a tall panel the card is as
  // tall as two doses with their notes, a reminder line and Taken need, or
  // more; on a square or short one (480x480) it is as tall as what it says.
  const tall = H >= k(700)
  const heroH = tall ? Math.round(Math.min(H * 0.55, Math.max(H * 0.42, k(350)))) : 0
  const boxH = tall ? wholeRows(H - 2 * pad - headH - heroH - 2 * gap, false) : 0
  return (
    <div className={`flex flex-col w-full h-full p-[${pad}px] gap-[${gap}px] ${t.page}`}>
      <div className={`h-[${headH}px] shrink-0 flex flex-col justify-center`}>
        <Head t={t} now={now} small={false} />
      </div>
      <div className={`${tall ? `h-[${heroH}px]` : ''} shrink-0 flex flex-col`}>
        <Hero t={t} size={tall ? 'lg' : 'md'} fill={tall} />
      </div>
      <List t={t} small={false} boxH={boxH} />
    </div>
  )
}

