// The schedule: one medication per line, its times and then its name, as
// someone types it on the frame's keyboard:
//
//   08:00 Vitamin D
//   08:00, 20:00 Metformin 500 mg - with food
//   every 8h from 07:00 Ibuprofen 200 mg
//   Mon Wed Fri 13:00 Iron
//
// Times are 08:00, 8:00, 8.00, 8am, 8:30 pm, noon or midnight. Days are
// Mon, Monday, Mondays, Mon-Fri, weekdays, weekends or daily (every day when
// none is said). "every 8h" (or 6 hours, 90 min) repeats from a "from" time
// (08:00 when none is said) up to an "until" time (the end of the day). The
// name may come first instead ("Vitamin D at 08:00"), a note after " - ", and
// a line starting with # is a comment. A line that cannot be read is a
// problem the scene shows, never a dose.

export type Med = { name: string; note: string; times: number[]; days: number; line: number }
export type Problem = { line: number; text: string; why: string }
export type Dose = { key: string; at: number; name: string; note: string; line: number }

export const EVERY_DAY = 127
// A line's doses in one day at most: "every 30 min" would be 48.
export const MAX_DOSES = 24

const DAY_NAMES = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday']
const clean = (word: string) => word.toLowerCase().replace(/[.,;:]+$/, '')

/** The weekday a word names (0 Sunday .. 6 Saturday), or -1: "mon",
 * "Monday", "mondays", "tues", "thurs", "weds", "mo". */
export function weekdayOf(word: string): number {
  const w = clean(word)
  if (w === 'weds') return 3
  if (w.length < 2) return -1
  for (let i = 0; i < 7; i++) {
    const full = DAY_NAMES[i]
    if (w === full + 's' || full.startsWith(w)) return i
  }
  return -1
}

/** The days a word names, as bits (1 << weekday), or 0: one day, a range
 * ("mon-fri", "fri-mon" goes round), "weekdays", "weekends", "daily". */
export function daysOf(word: string): number {
  const w = clean(word)
  if (w === 'daily' || w === 'everyday') return EVERY_DAY
  if (w === 'weekdays' || w === 'weekday') return 0b0111110
  if (w === 'weekends' || w === 'weekend') return 0b1000001
  const range = /^([a-z]+)[-–]([a-z]+)$/.exec(w)
  if (range) {
    const a = weekdayOf(range[1])
    const b = weekdayOf(range[2])
    if (a < 0 || b < 0) return 0
    let bits = 0
    for (let d = a; ; d = (d + 1) % 7) {
      bits |= 1 << d
      if (d === b) break
    }
    return bits
  }
  const d = weekdayOf(w)
  return d < 0 ? 0 : 1 << d
}

// A word that names days for certain, even after a time: a whole day name
// ("Sunday", "Sundays"), a range or a keyword. A short one ("Sun", "Sat")
// after a time may be the name's first word: "08:00 Sun cream".
function plainlyDays(word: string): boolean {
  const w = clean(word)
  if (/[-–]/.test(w) || ['daily', 'everyday', 'weekdays', 'weekday', 'weekends', 'weekend'].includes(w)) return true
  return DAY_NAMES.some((full) => w === full || w === full + 's')
}

// A clock time: minutes since midnight, BAD for one that cannot be a time
// ("25:00"), NONE for what is no time at all ("500").
const NONE = -1
const BAD = -2
function clockOf(word: string, meridiem: string): number {
  const w = word.toLowerCase().replace(/[,;:]+$/, '')
  if (w === 'noon' || w === 'midday') return 12 * 60
  if (w === 'midnight') return 0
  let m = /^(\d{1,2})[:.](\d{2})(am|pm|a\.m\.|p\.m\.)?$/.exec(w)
  if (!m) m = /^(\d{1,2})()(am|pm|a\.m\.|p\.m\.)$/.exec(w)
  // A bare hour is a time only with "am" or "pm" after it: "8 am".
  if (!m && meridiem) m = /^(\d{1,2})()()$/.exec(w)
  if (!m) return NONE
  let hour = Number(m[1])
  const minute = m[2] ? Number(m[2]) : 0
  const ampm = (m[3] || meridiem || '').charAt(0)
  if (minute > 59) return BAD
  if (ampm) {
    if (hour < 1 || hour > 12) return BAD
    hour = (hour % 12) + (ampm === 'p' ? 12 : 0)
  } else if (hour > 23) {
    return BAD
  }
  return hour * 60 + minute
}

const isMeridiem = (word: string | undefined) => !!word && /^(am|pm|a\.m\.|p\.m\.)[,;]?$/i.test(word)
const CONNECTORS = ['at', '@', 'and', '&', 'on', '+', '-', '–', '—', ',']

// An interval said after "every": "8h", "8 hours", "90 min", "1.5h". In
// minutes, with how many words it took; used 0 when it names none.
function intervalOf(words: string[], i: number): { minutes: number; used: number } {
  const units = 'h|hr|hrs|hour|hours|m|min|mins|minute|minutes'
  const one = new RegExp(`^(\\d+(?:[.,]\\d+)?)(${units})[,;]?$`, 'i').exec(words[i] || '')
  const two = /^(\d+(?:[.,]\d+)?)$/.exec(words[i] || '')
  const unit = two ? new RegExp(`^(${units})[,;]?$`, 'i').exec(words[i + 1] || '') : null
  if (!one && !(two && unit)) return { minutes: 0, used: 0 }
  const amount = Number((one ? one[1] : two![1]).replace(',', '.'))
  const hours = (one ? one[2] : unit![1]).toLowerCase().startsWith('h')
  return { minutes: Math.round(hours ? amount * 60 : amount), used: one ? 1 : 2 }
}

type Scan = {
  // How many words were read as the schedule, from the start.
  used: number
  times: number[]
  days: number
  every: number
  from: number
  until: number
  bad: string
}

// Reads the schedule's words from the start of `words` until a word that is
// none of them: a time (its am or pm may be the next word), days, "every
// ...", "from" or "until" a time, or a word that joins them ("at", "and", a
// comma). The words after are the name.
function scan(words: string[]): Scan {
  const out: Scan = { used: 0, times: [], days: 0, every: 0, from: NONE, until: NONE, bad: '' }
  const timeAt = (j: number): { minutes: number; used: number } => {
    if (isMeridiem(words[j + 1])) {
      const t = clockOf(words[j] || '', words[j + 1].replace(/[,;]$/, ''))
      if (t !== NONE) return { minutes: t, used: 2 }
    }
    return { minutes: clockOf(words[j] || '', ''), used: 1 }
  }
  let i = 0
  while (i < words.length) {
    const word = words[i]
    const lower = word.toLowerCase().replace(/[,;]+$/, '')
    if (lower === '' || CONNECTORS.includes(lower)) {
      i++
      continue
    }
    // Several times or days in one word, by commas: "08:00,20:00", "Mon,Wed".
    const parts = word.split(/[,;]/).filter((p) => p !== '')
    if (parts.length > 1) {
      const read = parts.map((p) => {
        const days = daysOf(p)
        return days ? { days, minutes: NONE } : { days: 0, minutes: clockOf(p, '') }
      })
      if (!read.every((p) => p.days || p.minutes !== NONE)) break
      for (const p of read) {
        if (p.minutes === BAD) out.bad = out.bad || `"${word}" is not a time`
        else if (p.days) out.days |= p.days
        else out.times.push(p.minutes)
      }
      i++
      continue
    }
    if (lower === 'every') {
      const next = clean(words[i + 1] || '')
      const days = next === 'day' ? EVERY_DAY : daysOf(next)
      if (days) {
        out.days |= days
        i += 2
        continue
      }
      const interval = intervalOf(words, i + 1)
      if (!interval.used) {
        out.bad = out.bad || '"every" needs a number of hours, like every 8h'
        i++
        continue
      }
      if (interval.minutes < 30 || interval.minutes > 24 * 60) out.bad = out.bad || 'repeat every 30 minutes to 24 hours'
      out.every = interval.minutes
      i += 1 + interval.used
      continue
    }
    if (lower === 'from' || lower === 'until' || lower === 'till' || lower === 'to') {
      const t = timeAt(i + 1)
      if (t.minutes === NONE) break
      if (t.minutes === BAD) out.bad = out.bad || `"${words[i + 1]}" is not a time`
      else if (lower === 'from') out.from = t.minutes
      else out.until = t.minutes
      i += 1 + t.used
      continue
    }
    const days = daysOf(word)
    if (days) {
      // After a time, one short day word followed by more words is the
      // name's start ("08:00 Sun cream"); two days or more are days
      // ("09:00 Mon Wed Fri Iron").
      let j = i + 1
      if (out.times.length && !plainlyDays(word)) {
        while (j < words.length && daysOf(words[j])) j++
        const after = words[j]
        const joins = after === undefined || CONNECTORS.includes(after.toLowerCase()) || timeAt(j).minutes !== NONE
        if (j - i < 2 && !joins) break
      }
      for (let d = i; d < j; d++) out.days |= daysOf(words[d])
      i = j
      continue
    }
    const t = timeAt(i)
    if (t.minutes === NONE) break
    if (t.minutes === BAD) out.bad = out.bad || `"${word}" is not a time`
    else out.times.push(t.minutes)
    i += t.used
  }
  out.used = i
  return out
}

const saysWhen = (s: Scan) => s.times.length > 0 || s.every > 0 || s.from !== NONE || s.bad !== ''

function expand(s: Scan): { times: number[]; why: string } {
  const times = s.times.slice()
  if (s.every) {
    // "every 8h 07:00 Ibuprofen": the one time said is where it starts.
    const start = s.from !== NONE ? s.from : times.length === 1 ? times.shift()! : 8 * 60
    const end = s.until !== NONE ? s.until : 24 * 60 - 1
    if (end < start) return { times: [], why: '"until" is before "from"' }
    for (let t = start; t <= end; t += s.every) {
      times.push(t)
      if (times.length > MAX_DOSES) return { times: [], why: 'too many doses in one day' }
    }
  } else if (s.from !== NONE) {
    times.push(s.from)
  }
  const unique = Array.from(new Set(times)).sort((a, b) => a - b)
  if (unique.length > MAX_DOSES) return { times: [], why: 'too many doses in one day' }
  return { times: unique, why: '' }
}

/** The medications a schedule names, and the lines it cannot read with why. */
export function parseSchedule(text: string): { meds: Med[]; problems: Problem[] } {
  const meds: Med[] = []
  const problems: Problem[] = []
  String(text || '')
    .split(/\r?\n/)
    .forEach((raw, index) => {
      const line = raw.trim()
      if (!line || line.startsWith('#') || line.startsWith('//')) return
      const words = line.split(/\s+/)
      // The times first, as the examples have it. Else the name first and the
      // times after it ("Vitamin D at 08:00", "Iron 09:00 Mon Wed Fri"): the
      // longest end of the line that is all schedule.
      let s = scan(words)
      let name = words.slice(s.used)
      if (!saysWhen(s)) {
        for (let k = 1; k < words.length; k++) {
          const back = scan(words.slice(k))
          if (back.used === words.length - k && saysWhen(back)) {
            s = back
            name = words.slice(0, k)
            break
          }
        }
      }
      const problem = (why: string) => {
        problems.push({ line: index + 1, text: line, why })
      }
      if (s.bad) return problem(s.bad)
      const { times, why } = expand(s)
      if (why) return problem(why)
      if (!times.length) return problem('no time. Write the time first, like 08:00 Vitamin D')
      // A note after " - ": "Metformin 500 mg - with food".
      const rest = name.join(' ')
      const dash = rest.search(/\s[-–—]\s/)
      const title = (dash >= 0 ? rest.slice(0, dash) : rest).replace(/^[-–—:\s]+/, '').trim()
      const note = dash >= 0 ? rest.slice(dash + 3).trim() : ''
      if (!title) return problem('no name after the time')
      meds.push({ name: title, note, times, days: s.days || EVERY_DAY, line: index + 1 })
    })
  return { meds, problems }
}

const pad = (n: number) => String(n).padStart(2, '0')

/** "08:00", or "8:00 am" on a 12-hour clock. */
export function timeLabel(minutes: number, twelve: boolean): string {
  const h = Math.floor(minutes / 60) % 24
  const m = pad(minutes % 60)
  return twelve ? `${h % 12 || 12}:${m} ${h < 12 ? 'am' : 'pm'}` : `${pad(h)}:${m}`
}

/** The doses of one day (its weekday), by time, then by line: each once,
 * keyed by its time and name, which is how a day's record knows it. */
export function dosesOn(meds: Med[], day: Date): Dose[] {
  const weekday = 1 << day.getDay()
  const seen = new Set<string>()
  const doses: Dose[] = []
  for (const med of meds) {
    if (!(med.days & weekday)) continue
    for (const at of med.times) {
      const key = `${timeLabel(at, false)} ${med.name}`
      if (seen.has(key)) continue
      seen.add(key)
      doses.push({ key, at, name: med.name, note: med.note, line: med.line })
    }
  }
  return doses.sort((a, b) => a.at - b.at || a.line - b.line)
}

sources.doses.ts:
// Where each of today's doses stands, when to ring and when to wake, and the
// day's record kept on disk. Pure: every function takes the moment it is
// (milliseconds since 1970) and reads days and times in the frame's time
// zone through Date's local fields, so a day is a day across a clock change.
import { dosesOn, type Dose, type Med } from './schedule'

export const MINUTE = 60 * 1000
// A dose woken for a little early still rings: a frame's clock and its sleep
// timer are not to the second.
export const EARLY_MS = 30 * 1000
// Rung again at most this many times, "Remind again after" apart.
export const MAX_AGAIN = 3
// With no reminder again, a dose not taken is missed after this long.
export const ALONE_MINUTES = 60
// The days of the strip: today and the six before it.
export const STRIP_DAYS = 7

/** The day's record: the day it is ("2026-11-28"), when the record began
 * (doses already missed then are not counted), each dose taken (by its key,
 * when), how many times each has rung, and the days before as
 * [day, taken, of]. */
export type Log = {
  day: string
  since: number
  taken: Record<string, number>
  rang: Record<string, number>
  days: Array<[string, number, number]>
}

export type Status = 'taken' | 'upcoming' | 'due' | 'missed' | 'untracked'
export type TimedDose = Dose & { moment: number }

const pad = (n: number) => String(n).padStart(2, '0')

/** The day a moment falls on, in the frame's time zone: "2026-11-28". */
export function dayKey(when: Date): string {
  return `${when.getFullYear()}-${pad(when.getMonth() + 1)}-${pad(when.getDate())}`
}

/** Midnight at the start of a day key, local. */
export function dayOf(key: string): Date {
  const [y, m, d] = key.split('-').map(Number)
  return new Date(y, m - 1, d)
}

/** A day so many days from another, by the calendar (never 24 hours: a
 * clock change makes a day 23 or 25). */
export function plusDays(day: Date, days: number): Date {
  return new Date(day.getFullYear(), day.getMonth(), day.getDate() + days)
}

/** The moment of a clock time on a day. A time a clock change skips (02:30
 * when 02:00 jumps to 03:00) is the moment after it. */
export function momentOf(day: Date, minutes: number): number {
  return new Date(day.getFullYear(), day.getMonth(), day.getDate(), Math.floor(minutes / 60), minutes % 60, 0, 0).getTime()
}

/** A day's doses with their moments. */
export function timedDoses(meds: Med[], day: Date): TimedDose[] {
  return dosesOn(meds, day).map((dose) => ({ ...dose, moment: momentOf(day, dose.at) }))
}

/** How long after its time a dose not taken is missed: after its last
 * reminder and as long again, or an hour with none. */
export const missAfterMs = (again: number) => (again > 0 ? (MAX_AGAIN + 1) * again : ALONE_MINUTES) * MINUTE

/** Where a dose stands: taken, still to come, due (rung, waiting to be
 * taken), missed, or not counted (already missed when the record began). */
export function statusOf(dose: TimedDose, now: number, log: Log, again: number): Status {
  if (log.taken[dose.key]) return 'taken'
  if (now + EARLY_MS < dose.moment) return 'upcoming'
  const missAt = dose.moment + missAfterMs(again)
  if (missAt <= log.since) return 'untracked'
  if (now >= missAt) return 'missed'
  return 'due'
}

/** How many times a dose should have rung by now: once at its time, then
 * once more every `again` minutes, MAX_AGAIN times at most. */
export function ringsDue(moment: number, now: number, again: number): number {
  if (now + EARLY_MS < moment) return 0
  if (again <= 0) return 1
  return Math.min(MAX_AGAIN + 1, Math.floor((now + EARLY_MS - moment) / (again * MINUTE)) + 1)
}

/** The doses to ring for now: due, and rung fewer times than they should
 * have been. A missed one (the frame was off for hours) never rings. */
export function toRing(doses: TimedDose[], now: number, log: Log, again: number): Record<string, number> {
  const ring: Record<string, number> = {}
  for (const dose of doses) {
    if (statusOf(dose, now, log, again) !== 'due') continue
    const count = ringsDue(dose.moment, now, again)
    if (count > (log.rang[dose.key] || 0)) ring[dose.key] = count
  }
  return ring
}

/** When the next reminder rings for a due dose (null when it has rung its
 * last). */
export function nextRingAt(dose: TimedDose, now: number, again: number): number | null {
  if (again <= 0) return null
  const count = ringsDue(dose.moment, now, again)
  return count <= MAX_AGAIN ? dose.moment + count * again * MINUTE : null
}

/** The next moment something changes: a dose comes, a reminder rings again,
 * a dose goes from due to missed, or the day ends (a new checklist). */
export function nextChange(doses: TimedDose[], now: number, log: Log, again: number): number {
  let next = plusDays(new Date(now), 1).getTime()
  for (const dose of doses) {
    const status = statusOf(dose, now, log, again)
    if (status === 'upcoming') next = Math.min(next, dose.moment)
    if (status !== 'due') continue
    const ring = nextRingAt(dose, now, again)
    if (ring !== null) next = Math.min(next, ring)
    next = Math.min(next, dose.moment + missAfterMs(again))
  }
  return next
}

/** Seconds to sleep until `next`, at least 1 and at most `cap`. */
export const secondsUntil = (next: number, now: number, cap: number) => Math.min(cap, Math.max(1, Math.ceil((next - now) / 1000)))

/** A new record, begun now. */
export const freshLog = (now: number): Log => ({ day: dayKey(new Date(now)), since: now, taken: {}, rang: {}, days: [] })

/** The record kept in state, or a new one: what is not a record is none. */
export function readLog(kept: unknown, now: number): Log {
  let value: any = kept
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value)
    } catch (e) {
      value = null
    }
  }
  if (!value || typeof value !== 'object' || typeof value.day !== 'string' || !/^\d{4}-\d\d-\d\d$/.test(value.day)) return freshLog(now)
  const record = (v: any) => (v && typeof v === 'object' && !Array.isArray(v) ? v : {})
  return {
    day: value.day,
    since: typeof value.since === 'number' ? value.since : 0,
    taken: record(value.taken),
    rang: record(value.rang),
    days: Array.isArray(value.days) ? value.days.filter((d: any) => Array.isArray(d) && typeof d[0] === 'string') : [],
  }
}

/** How a day went: doses taken of those counted. */
export function tally(doses: TimedDose[], now: number, log: Log, again: number) {
  let taken = 0
  let of = 0
  let missed = 0
  let due = 0
  for (const dose of doses) {
    const status = statusOf(dose, now, log, again)
    if (status === 'untracked') continue
    of++
    if (status === 'taken') taken++
    if (status === 'missed') missed++
    if (status === 'due') due++
  }
  return { taken, of, missed, due }
}

/** The record for the day `now` falls on. On a new day the day before goes
 * into the history (its doses as the schedule has them now) and today's
 * checklist starts empty; the history keeps the days the strip shows. A
 * clock set back starts the day again without history. */
export function rollDay(log: Log, meds: Med[], now: number, again: number): Log {
  const today = dayKey(new Date(now))
  if (log.day === today) return log
  let days = log.days
  if (log.day < today) {
    const before = dayOf(log.day)
    // The day before as it ended: whatever was not taken then is missed.
    const { taken, of } = tally(timedDoses(meds, before), plusDays(before, 2).getTime(), log, again)
    days = [...days.filter((d) => d[0] !== log.day), [log.day, taken, of] as [string, number, number]]
  }
  const oldest = dayKey(plusDays(dayOf(today), -STRIP_DAYS))
  days = days.filter((d) => d[0] > oldest && d[0] < today).sort((a, b) => (a[0] < b[0] ? -1 : 1))
  return { day: today, since: log.since, taken: {}, rang: {}, days }
}

/** The strip's days, oldest first, ending today: each its key, its weekday
 * (0 Sunday), and taken of counted, -1 of for a day with no record. */
export function stripDays(log: Log, today: { taken: number; of: number }, now: number) {
  const day = new Date(now)
  const cells: Array<{ key: string; weekday: number; taken: number; of: number; today: boolean }> = []
  for (let back = STRIP_DAYS - 1; back >= 0; back--) {
    const d = plusDays(day, -back)
    const key = dayKey(d)
    const kept = back === 0 ? [key, today.taken, today.of] : log.days.find((entry) => entry[0] === key)
    cells.push({ key, weekday: d.getDay(), taken: kept ? Number(kept[1]) || 0 : 0, of: kept ? Number(kept[2]) || 0 : -1, today: back === 0 })
  }
  return cells
}

sources.app.test.ts:
import { get, onEvent } from './app'
import { EVERY_DAY, dosesOn, parseSchedule, timeLabel } from './schedule'
import {
  dayKey,
  freshLog,
  momentOf,
  nextChange,
  plusDays,
  readLog,
  ringsDue,
  rollDay,
  secondsUntil,
  statusOf,
  stripDays,
  timedDoses,
  toRing,
} from './doses'

// Every moment here is made from the zone the test runs in, as the frame
// reads its own: the tests hold in Brussels, New York or Tokyo alike.
const MINUTE = 60 * 1000
const at = (y: number, m: number, d: number, h = 0, min = 0) => new Date(y, m - 1, d, h, min, 0, 0).getTime()
// Saturday 28 November 2026.
const SAT = (h: number, min = 0) => at(2026, 11, 28, h, min)

function clock<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

const parse = (text: string) => parseSchedule(text)
const one = (text: string) => {
  const { meds, problems } = parse(text)
  expect(problems).toEqual([])
  expect(meds.length).toBe(1)
  return meds[0]
}
const bits = (...days: number[]) => days.reduce((b, d) => b | (1 << d), 0)

describe('reading the schedule', () => {
  it('reads a time and a name', () => {
    expect(one('08:00 Vitamin D')).toEqual({ name: 'Vitamin D', note: '', times: [480], days: EVERY_DAY, line: 1 })
    expect(one('8:30 Fish oil').times).toEqual([510])
    expect(one('7.45 Eye drops').times).toEqual([465])
    expect(one('8am Vitamin D').times).toEqual([480])
    expect(one('8 pm Melatonin').times).toEqual([1200])
    expect(one('12:15am Night pill').times).toEqual([15])
    expect(one('12pm Lunch pill').times).toEqual([720])
    expect(one('noon Iron').times).toEqual([720])
    expect(one('midnight Late pill').times).toEqual([0])
  })

  it('reads several times, by commas, "and" or spaces, sorted and once each', () => {
    expect(one('08:00, 20:00 Metformin 500 mg')).toMatchObject({ name: 'Metformin 500 mg', times: [480, 1200] })
    expect(one('20:00,08:00 Metformin').times).toEqual([480, 1200])
    expect(one('8am and 8pm Metformin').times).toEqual([480, 1200])
    expect(one('08:00 14:00 20:00 Antibiotic').times).toEqual([480, 840, 1200])
    expect(one('08:00, 08:00 Twice written').times).toEqual([480])
  })

  it('keeps a note after a dash, and a dash in the name', () => {
    expect(one('08:00 Metformin 500 mg - with food')).toMatchObject({ name: 'Metformin 500 mg', note: 'with food' })
    expect(one('08:00 - Vitamin D')).toMatchObject({ name: 'Vitamin D', note: '' })
    expect(one('08:00 5-HTP')).toMatchObject({ name: '5-HTP', note: '' })
  })

  it('repeats "every" so many hours from a time, up to an end', () => {
    expect(one('every 8h from 07:00 Ibuprofen').times).toEqual([420, 900, 1380])
    expect(one('every 8 hours from 7am Ibuprofen').times).toEqual([420, 900, 1380])
    expect(one('every 6h Paracetamol').times).toEqual([480, 840, 1200])
    expect(one('every 4h from 08:00 until 20:00 Paracetamol').times).toEqual([480, 720, 960, 1200])
    expect(one('every 90 min from 9:00 to 12:00 Drops').times).toEqual([540, 630, 720])
    expect(one('every 12h 09:00 Eye drops').times).toEqual([540, 1260])
  })

  it('reads days: names, ranges, weekdays, weekends, daily', () => {
    expect(one('Mon Wed Fri 09:00 Iron')).toMatchObject({ name: 'Iron', days: bits(1, 3, 5) })
    expect(one('Mon,Wed,Fri 09:00 Iron').days).toBe(bits(1, 3, 5))
    expect(one('Mon-Fri 08:00 Work pill').days).toBe(bits(1, 2, 3, 4, 5))
    expect(one('Fri-Mon 08:00 Long weekend').days).toBe(bits(5, 6, 0, 1))
    expect(one('weekdays 08:00 A').days).toBe(bits(1, 2, 3, 4, 5))
    expect(one('weekends 10:00 B').days).toBe(bits(0, 6))
    expect(one('daily 10:00 C').days).toBe(EVERY_DAY)
    expect(one('Sundays at 9am Vitamin B12').days).toBe(bits(0))
    expect(one('every Tuesday 08:00 Methotrexate').days).toBe(bits(2))
    expect(one('Tues Thurs 08:00 D').days).toBe(bits(2, 4))
    // Days after the time, when there are two or more of them.
    expect(one('09:00 Mon Wed Fri Iron')).toMatchObject({ name: 'Iron', days: bits(1, 3, 5) })
  })

  it('takes the name first, with the times after it', () => {
    expect(one('Vitamin D at 08:00')).toMatchObject({ name: 'Vitamin D', times: [480], days: EVERY_DAY })
    expect(one('Metformin 500 mg 8am, 8pm')).toMatchObject({ name: 'Metformin 500 mg', times: [480, 1200] })
    expect(one('Iron 09:00 Mon Wed Fri')).toMatchObject({ name: 'Iron', days: bits(1, 3, 5) })
    expect(one('Ibuprofen every 8h from 07:00')).toMatchObject({ name: 'Ibuprofen', times: [420, 900, 1380] })
    expect(one('Aspirin 81 at 9 pm')).toMatchObject({ name: 'Aspirin 81', times: [1260] })
  })

  it('keeps a word that only looks like a day in the name', () => {
    expect(one('08:00 Sun cream')).toMatchObject({ name: 'Sun cream', days: EVERY_DAY })
    expect(one('Sun cream 08:00')).toMatchObject({ name: 'Sun cream', days: EVERY_DAY })
    expect(one('Sat 08:00 Sun cream')).toMatchObject({ name: 'Sun cream', days: bits(6) })
  })

  it('skips blank lines and comments, and counts lines as typed', () => {
    const { meds, problems } = parse('# morning\n\n08:00 A\n   \n// evening\n20:00 B\n')
    expect(problems).toEqual([])
    expect(meds.map((m) => [m.name, m.line])).toEqual([['A', 3], ['B', 6]])
  })

  it('says why it cannot read a line, and reads the others', () => {
    const { meds, problems } = parse('Vitamin D\n08:00\n25:00 Iron\n13pm Zinc\nevery other day 08:00 X\nevery 10 min Y\n08:00 Fine\nevery 8h from 20:00 until 08:00 Z')
    expect(meds.map((m) => m.name)).toEqual(['Fine'])
    expect(problems.map((p) => [p.line, p.why])).toEqual([
      [1, 'no time. Write the time first, like 08:00 Vitamin D'],
      [2, 'no name after the time'],
      [3, '"25:00" is not a time'],
      [4, '"13pm" is not a time'],
      [5, '"every" needs a number of hours, like every 8h'],
      [6, 'repeat every 30 minutes to 24 hours'],
      [8, '"until" is before "from"'],
    ])
    expect(problems[0].text).toBe('Vitamin D')
  })

  it('leaves amounts alone: a bare number is no time', () => {
    expect(one('08:00 Vitamin D 1000 IU')).toMatchObject({ name: 'Vitamin D 1000 IU', times: [480] })
    expect(parse('2 tablets Paracetamol').problems.length).toBe(1)
  })
})

describe('a day of doses', () => {
  const { meds } = parse('Mon Wed Fri 13:00 Iron\n08:00, 20:00 Metformin\n08:00 Vitamin D\nevery 8h from 07:00 Ibuprofen')

  it('lists the day\'s doses by time, then by line, keyed by time and name', () => {
    const saturday = dosesOn(meds, new Date(2026, 10, 28))
    expect(saturday.map((d) => d.key)).toEqual(['07:00 Ibuprofen', '08:00 Metformin', '08:00 Vitamin D', '15:00 Ibuprofen', '20:00 Metformin', '23:00 Ibuprofen'])
    const monday = dosesOn(meds, new Date(2026, 10, 30))
    expect(monday.map((d) => d.key)).toContain('13:00 Iron')
  })

  it('writes a time on a 24- or 12-hour clock', () => {
    expect(timeLabel(480, false)).toBe('08:00')
    expect(timeLabel(1200, true)).toBe('8:00 pm')
    expect(timeLabel(0, true)).toBe('12:00 am')
    expect(timeLabel(720, true)).toBe('12:00 pm')
  })

  it('puts a dose at its clock time on the day of a clock change', () => {
    // 29 March 2026 (Europe) and 8 March 2026 (US) are 23 hours long where
    // the clocks change; 25 October and 1 November 25 hours.
    for (const [y, m, d] of [[2026, 3, 29], [2026, 3, 8], [2026, 10, 25], [2026, 11, 1]]) {
      const day = new Date(y, m - 1, d)
      const timed = timedDoses(meds, day)
      const vitamin = timed.find((x) => x.name === 'Vitamin D')!
      expect(vitamin.moment).toBe(at(y, m, d, 8))
      expect(new Date(vitamin.moment).getHours()).toBe(8)
      expect(dayKey(new Date(vitamin.moment))).toBe(dayKey(day))
      // The next day is the next calendar day, never 24 hours on.
      expect(dayKey(plusDays(day, 1))).toBe(dayKey(new Date(y, m - 1, d + 1)))
      expect(new Date(momentOf(plusDays(day, 1), 480)).getHours()).toBe(8)
    }
  })

  it('names the day in the frame\'s zone, and steps by days across a clock change', () => {
    expect(dayKey(new Date(at(2026, 3, 29, 0, 30)))).toBe('2026-03-29')
    expect(dayKey(new Date(at(2026, 3, 29, 23, 59)))).toBe('2026-03-29')
    // From half past midnight the day after the change, six days back.
    const keys = stripDays(freshLog(0), { taken: 0, of: 0 }, at(2026, 3, 30, 0, 30)).map((c) => c.key)
    expect(keys).toEqual(['2026-03-24', '2026-03-25', '2026-03-26', '2026-03-27', '2026-03-28', '2026-03-29', '2026-03-30'])
    const autumn = stripDays(freshLog(0), { taken: 0, of: 0 }, at(2026, 10, 26, 23, 30)).map((c) => c.key)
    expect(autumn[0]).toBe('2026-10-20')
    expect(autumn[6]).toBe('2026-10-26')
  })
})

describe('where a dose stands', () => {
  const dose = timedDoses(parse('08:00 Vitamin D').meds, new Date(2026, 10, 28))[0]
  const log = { ...freshLog(SAT(6)) }

  it('is to come, due from its time (30 s early too), and missed after its reminders', () => {
    expect(statusOf(dose, SAT(7, 59), log, 10)).toBe('upcoming')
    expect(statusOf(dose, SAT(8) - 20 * 1000, log, 10)).toBe('due')
    expect(statusOf(dose, SAT(8, 39), log, 10)).toBe('due')
    expect(statusOf(dose, SAT(8, 40), log, 10)).toBe('missed')
    // With no reminder again, an hour.
    expect(statusOf(dose, SAT(8, 59), log, 0)).toBe('due')
    expect(statusOf(dose, SAT(9), log, 0)).toBe('missed')
  })

  it('is taken once marked, whenever that was', () => {
    const taken = { ...log, taken: { '08:00 Vitamin D': SAT(8, 12) } }
    expect(statusOf(dose, SAT(8, 13), taken, 10)).toBe('taken')
    expect(statusOf(dose, SAT(23), taken, 10)).toBe('taken')
  })

  it('is not counted when it was missed before the record began', () => {
    const late = freshLog(SAT(14))
    expect(statusOf(dose, SAT(14), late, 10)).toBe('untracked')
    // Due when the record began: counted.
    expect(statusOf(dose, SAT(8, 10), freshLog(SAT(8, 5)), 10)).toBe('due')
  })
})

describe('ringing', () => {
  const doses = timedDoses(parse('08:00 Vitamin D\n08:00 Metformin\n20:00 Metformin').meds, new Date(2026, 10, 28))
  const begun = freshLog(SAT(6))

  it('rings once at the time, and again every so often, three times more at most', () => {
    expect(ringsDue(SAT(8), SAT(7, 59), 10)).toBe(0)
    expect(ringsDue(SAT(8), SAT(8) - 30 * 1000, 10)).toBe(1)
    expect(ringsDue(SAT(8), SAT(8, 9), 10)).toBe(1)
    expect(ringsDue(SAT(8), SAT(8, 10), 10)).toBe(2)
    expect(ringsDue(SAT(8), SAT(8, 35), 10)).toBe(4)
    expect(ringsDue(SAT(8), SAT(9), 10)).toBe(4)
    expect(ringsDue(SAT(8), SAT(9), 0)).toBe(1)
  })

  it('rings for what is due and has not rung yet, never for what is missed or taken', () => {
    expect(toRing(doses, SAT(8), begun, 10)).toEqual({ '08:00 Vitamin D': 1, '08:00 Metformin': 1 })
    const rung = { ...begun, rang: { '08:00 Vitamin D': 1, '08:00 Metformin': 1 } }
    expect(toRing(doses, SAT(8, 5), rung, 10)).toEqual({})
    const oneTaken = { ...rung, taken: { '08:00 Metformin': SAT(8, 3) } }
    expect(toRing(doses, SAT(8, 10), oneTaken, 10)).toEqual({ '08:00 Vitamin D': 2 })
    // Missed by hours (the frame was off): nothing rings.
    expect(toRing(doses, SAT(14), begun, 10)).toEqual({})
  })

  it('wakes for the next reminder, the dose turning missed, the next dose, or midnight', () => {
    expect(nextChange(doses, SAT(7), begun, 10)).toBe(SAT(8))
    const rung = { ...begun, rang: { '08:00 Vitamin D': 1, '08:00 Metformin': 1 } }
    expect(nextChange(doses, SAT(8, 1), rung, 10)).toBe(SAT(8, 10))
    expect(nextChange(doses, SAT(8, 31), rung, 10)).toBe(SAT(8, 40))
    expect(nextChange(doses, SAT(8, 31), rung, 0)).toBe(SAT(9))
    expect(nextChange(doses, SAT(9), rung, 10)).toBe(SAT(20))
    // Nothing left today: the new day.
    expect(nextChange(doses, SAT(21), begun, 10)).toBe(at(2026, 11, 29))
    expect(secondsUntil(SAT(8), SAT(7), 3600)).toBe(3600)
    expect(secondsUntil(SAT(8), SAT(7, 50), 3600)).toBe(600)
    expect(secondsUntil(SAT(8), SAT(8) + 200, 3600)).toBe(1)
  })
})

describe('the day\'s record', () => {
  const { meds } = parse('08:00 Vitamin D\n08:00, 20:00 Metformin')

  it('reads what is kept, and starts a new record from anything else', () => {
    expect(readLog(null, SAT(9))).toEqual(freshLog(SAT(9)))
    expect(readLog('nonsense', SAT(9)).day).toBe('2026-11-28')
    expect(readLog({ day: 'yesterday' }, SAT(9)).since).toBe(SAT(9))
    const kept = { day: '2026-11-28', since: 5, taken: { a: 1 }, rang: { a: 2 }, days: [['2026-11-27', 1, 2], 'bad'] }
    expect(readLog(kept, SAT(9))).toEqual({ day: '2026-11-28', since: 5, taken: { a: 1 }, rang: { a: 2 }, days: [['2026-11-27', 1, 2]] })
    expect(readLog(JSON.stringify(kept), SAT(9)).taken).toEqual({ a: 1 })
  })

  it('starts each day empty and keeps how the day before went', () => {
    const friday = { day: '2026-11-27', since: 0, taken: { '08:00 Vitamin D': at(2026, 11, 27, 8, 5), '08:00 Metformin': at(2026, 11, 27, 8, 5) }, rang: { '20:00 Metformin': 4 }, days: [] }
    const rolled = rollDay(friday, meds, SAT(0, 1), 10)
    expect(rolled.day).toBe('2026-11-28')
    expect(rolled.taken).toEqual({})
    expect(rolled.rang).toEqual({})
    expect(rolled.days).toEqual([['2026-11-27', 2, 3]])
    // The same day: the same record.
    expect(rollDay(rolled, meds, SAT(23, 59), 10)).toBe(rolled)
  })

  it('keeps only the days the strip shows, and draws them oldest first with today last', () => {
    const days: Array<[string, number, number]> = []
    for (let d = 10; d <= 26; d++) days.push([`2026-11-${d}`, 3, 3])
    const rolled = rollDay({ day: '2026-11-27', since: 0, taken: {}, rang: {}, days }, meds, SAT(7), 10)
    expect(rolled.days.map((d) => d[0])).toEqual(['2026-11-22', '2026-11-23', '2026-11-24', '2026-11-25', '2026-11-26', '2026-11-27'])
    expect(rolled.days[5]).toEqual(['2026-11-27', 0, 3])
    const cells = stripDays(rolled, { taken: 1, of: 3 }, SAT(9))
    expect(cells.map((c) => [c.key, c.taken, c.of])).toEqual([
      ['2026-11-22', 3, 3], ['2026-11-23', 3, 3], ['2026-11-24', 3, 3], ['2026-11-25', 3, 3],
      ['2026-11-26', 3, 3], ['2026-11-27', 0, 3], ['2026-11-28', 1, 3],
    ])
    expect(cells[6].today).toBe(true)
    expect(cells[6].weekday).toBe(6)
  })

  it('leaves out of the history the days the frame was off', () => {
    const rolled = rollDay({ day: '2026-11-20', since: 0, taken: {}, rang: {}, days: [] }, meds, SAT(9), 10)
    expect(rolled.days).toEqual([])
    const cells = stripDays(rolled, { taken: 0, of: 3 }, SAT(9))
    expect(cells.slice(0, 6).every((c) => c.of === -1)).toBe(true)
  })
})

describe('the scene', () => {
  const schedule = '08:00 Vitamin D\n20:00 Metformin'
  const kept = (extra = {}) => ({ day: '2026-11-28', since: SAT(0), taken: {}, rang: {}, days: [], ...extra })

  it('chimes once when a dose comes, and keeps that it rang', () => {
    const tone = mock.tone(() => true)
    const app = makeApp({ state: { schedule, log: kept() } })
    clock(SAT(8) - 10 * 1000, () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(1)
    expect(app.state.log.rang).toEqual({ '08:00 Vitamin D': 1 })
    // A tap or the next render a minute later: no sound.
    clock(SAT(8, 1), () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(1)
    // Ten minutes on, not taken: again.
    clock(SAT(8, 10), () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(2)
    expect(app.state.log.rang).toEqual({ '08:00 Vitamin D': 2 })
  })

  it('wakes the frame for the dose, the reminder after it, and within the hour', () => {
    mock.tone(() => true)
    const app = makeApp({ state: { schedule, log: kept() } })
    clock(SAT(7, 50), () => get(app, makeContext()))
    expect(app.nextSleep).toBe(600)
    clock(SAT(8), () => get(app, makeContext()))
    expect(app.nextSleep).toBe(600)
    clock(SAT(9), () => get(app, makeContext()))
    expect(app.nextSleep).toBe(3600)
    // The scene's own interval caps it.
    const often = makeApp({ state: { schedule, log: kept(), refreshInterval: 300 } })
    clock(SAT(9), () => get(often, makeContext()))
    expect(often.nextSleep).toBe(300)
  })

  it('stays quiet with its sound off, for one missed by hours, and where tone does not exist', () => {
    const tone = mock.tone(() => true)
    const quiet = makeApp({ state: { schedule, sound: false, log: kept() } })
    clock(SAT(8), () => get(quiet, makeContext()))
    expect(quiet.state.log.rang).toEqual({ '08:00 Vitamin D': 1 })
    const late = makeApp({ state: { schedule, log: kept() } })
    clock(SAT(14), () => get(late, makeContext()))
    expect(late.state.log.rang).toEqual({})
    expect(tone).toHaveBeenCalledTimes(0)
    const real = frameos.tone
    try {
      ;(frameos as any).tone = undefined
      const old = makeApp({ state: { schedule, log: kept() } })
      clock(SAT(8), () => get(old, makeContext()))
      expect(old.state.log.rang).toEqual({ '08:00 Vitamin D': 1 })
    } finally {
      ;(frameos as any).tone = real
    }
  })

  it('marks what is due as taken with the frame\'s Action key, and no reminder follows', () => {
    const tone = mock.tone(() => true)
    const app = makeApp({ state: { schedule, log: kept() } })
    clock(SAT(8), () => get(app, makeContext()))
    const press = { event: 'button', payload: { label: 'REFRESH', role: 'primary', action: 'press' } }
    expect(clock(SAT(8, 3), () => onEvent(app, press))).toBe(true)
    expect(app.state.log.taken).toEqual({ '08:00 Vitamin D': SAT(8, 3) })
    clock(SAT(8, 10), () => get(app, makeContext()))
    expect(tone).toHaveBeenCalledTimes(1)
    // Nothing due: the key is the UI's.
    expect(clock(SAT(8, 11), () => onEvent(app, press))).toBe(false)
    expect(clock(SAT(8), () => onEvent(app, { event: 'button', payload: { role: 'next', action: 'press' } }))).toBe(false)
  })

  it('starts a new record on the first render, without counting what was missed before it', () => {
    mock.tone(() => true)
    const app = makeApp({ state: { schedule } })
    clock(SAT(14), () => get(app, makeContext()))
    expect(app.state.log).toMatchObject({ day: '2026-11-28', since: SAT(14), taken: {}, rang: {} })
    expect(statusOf(timedDoses(parse(schedule).meds, new Date(SAT(0)))[0], SAT(14), app.state.log, 10)).toBe('untracked')
  })

  it('rolls over at midnight in the frame\'s zone', () => {
    mock.tone(() => true)
    const app = makeApp({ state: { schedule, log: kept({ taken: { '08:00 Vitamin D': SAT(8, 2) } }) } })
    clock(at(2026, 11, 29, 0, 0) + 5 * 1000, () => get(app, makeContext()))
    expect(app.state.log.day).toBe('2026-11-29')
    expect(app.state.log.taken).toEqual({})
    expect(app.state.log.days).toEqual([['2026-11-28', 1, 2]])
  })

  it('brings a round panel back from its list when a dose rings, and Back closes the list', () => {
    mock.tone(() => true)
    const app = makeApp({ state: { schedule, log: kept() }, frame: { width: 466, height: 466, round: true } })
    frameos.remember('page', 'list')
    clock(SAT(7), () => get(app, makeContext({ round: true })))
    expect(frameos.recall('page')).toBe('list')
    expect(clock(SAT(7, 1), () => onEvent(app, { event: 'back', payload: {} }))).toBe(true)
    expect(frameos.recall('page')).toBe('now')
    expect(clock(SAT(7, 2), () => onEvent(app, { event: 'back', payload: {} }))).toBe(false)
    frameos.remember('page', 'list')
    clock(SAT(8), () => get(app, makeContext({ round: true })))
    expect(frameos.recall('page')).toBe('now')
  })

  it('draws on every panel without throwing', () => {
    mock.tone(() => true)
    for (const [width, height] of [[800, 480], [480, 800], [240, 320], [1200, 1600]]) {
      const app = makeApp({ state: { schedule, log: kept() }, frame: { width, height } })
      const image = clock(SAT(8), () => get(app, makeContext()))
      expect(typeof image).toBe('object')
    }
    const round = makeApp({ state: { schedule: '', log: kept() }, frame: { width: 466, height: 466, round: true } })
    expect(typeof clock(SAT(8), () => get(round, makeContext({ round: true })))).toBe('object')
  })
})
